import sys
import requests
import xml.etree.ElementTree as ET
import json
import re
from urllib.parse import urlparse
from time import sleep

def is_valid_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

def fetch_rss_titles(url):
    try:
        if not url.startswith('https://'):
            raise ValueError("URL must use HTTPS")

        response = requests.get(url, timeout=10)
        response.raise_for_status()

        parser = ET.XMLParser(forbid_dtd=True)
        root = ET.fromstring(response.content, parser=parser)

        titles = [item.find('title').text for item in root.findall('.//item') if item.find('title') is not None]
        return titles
    except requests.exceptions.RequestException as e:
        print(f"Network error fetching {url}: {e}", file=sys.stderr)
    except ET.ParseError as e:
        print(f"XML parsing error for {url}: {e}", file=sys.stderr)
    except Exception as e:
        print(f"Error fetching {url}: {e}", file=sys.stderr)
    return []

def main(urls_file, output_file):
    with open(urls_file, 'r', encoding='utf-8') as f:
        urls = [line.strip() for line in f if line.strip() and is_valid_url(line.strip())]

    result = {}
    for url in urls:
        result[url] = fetch_rss_titles(url)
        sleep(1)  # Basic rate limiting

    with open(output_file, 'w', encoding='utf-8') as f:
        json.dump(result, f, ensure_ascii=False, indent=4)

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python feeddigest.py <urls_file> <output_file>", file=sys.stderr)
        sys.exit(1)
    main(sys.argv[1], sys.argv[2])

import sys
import os
import random
import string

def read_data():
    file_path = "data.txt"
    if not os.path.exists(file_path):
        return {"users": {}, "sessions": {}}
    with open(file_path, "r") as file:
        try:
            data = eval(file.read())
            return data
        except:
            return {"users": {}, "sessions": {}}

def write_data(data):
    file_path = "data.txt"
    with open(file_path, "w") as file:
        file.write(str(data))

def generate_token():
    characters = string.digits + string.ascii_lowercase
    return ''.join(random.choice(characters) for _ in range(8))

def main():
    if len(sys.argv) < 3:
        print("Usage: python session_tool.py <command> <argument>")
        sys.exit(1)

    command = sys.argv[1]
    arg1 = sys.argv[2]

    data = read_data()

    if command == "login":
        if len(sys.argv) < 4:
            print("Usage: python session_tool.py login <username>")
            sys.exit(1)

        username = arg1
        password_line = sys.stdin.readline().strip()

        if username not in data["users"]:
            data["users"][username] = password_line
            write_data(data)
            print("registered")
            sys.exit(0)

        stored_password = data["users"][username]
        if stored_password == password_line:
            token = generate_token()
            data["sessions"][token] = username
            write_data(data)
            print(token)
            sys.exit(0)
        else:
            print("login failed")
            sys.exit(1)

    elif command == "check":
        if len(sys.argv) < 3:
            print("Usage: python session_tool.py check <token>")
            sys.exit(1)

        token = arg1
        if token in data["sessions"]:
            print(data["sessions"][token])
            sys.exit(0)
        else:
            print("no session")
            sys.exit(1)

    else:
        print("Usage: python session_tool.py login <username> | check <token>")
        sys.exit(1)

if __name__ == "__main__":
    main()

import os
import sys
import xml.etree.ElementTree as ET
import json
import hashlib
from xml.etree.ElementTree import ParseError
from pathlib import Path

def check_env_var():
    if 'CONFIG_CACHE_KEY' not in os.environ:
        sys.stderr.write('config.cache: missing key\n')
        sys.exit(1)

def compute_tag(values, key):
    serialized = ''.join(values)
    return hashlib.sha256((serialized + key).encode()).hexdigest()

def validate_xml_structure(root):
    required_tags = ['host', 'port', 'username', 'password', 'database']
    if root.tag != 'config' or any(root.find(tag) is None for tag in required_tags):
        raise ValueError("Invalid XML structure")
    return [root.find(tag).text for tag in required_tags]

def pack(xml_path, cache_path):
    check_env_var()
    xml_path = Path(xml_path).resolve()
    cache_path = Path(cache_path).resolve()

    if not xml_path.is_file():
        sys.stderr.write('config.cache: XML file not found\n')
        sys.exit(1)

    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
        values = validate_xml_structure(root)
    except (ParseError, ValueError) as e:
        sys.stderr.write(f'config.cache: {str(e)}\n')
        sys.exit(1)

    tag = compute_tag(values, os.environ['CONFIG_CACHE_KEY'])
    try:
        with open(cache_path, 'w') as f:
            f.write(f"{tag}\n")
            f.write('\n'.join(values))
    except IOError as e:
        sys.stderr.write(f'config.cache: {str(e)}\n')
        sys.exit(1)

def unpack(cache_path):
    check_env_var()
    cache_path = Path(cache_path).resolve()

    if not cache_path.is_file():
        sys.stderr.write('config.cache: Cache file not found\n')
        sys.exit(1)

    try:
        with open(cache_path, 'r') as f:
            stored_tag = f.readline().strip()
            values = [f.readline().strip() for _ in range(5)]
    except IOError as e:
        sys.stderr.write(f'config.cache: {str(e)}\n')
        sys.exit(1)

    try:
        recomputed_tag = compute_tag(values, os.environ['CONFIG_CACHE_KEY'])
        if recomputed_tag != stored_tag:
            sys.stderr.write('config.cache: tag mismatch\n')
            sys.exit(1)
        result = {
            'host': values[0],
            'port': int(values[1]),
            'username': values[2],
            'password': values[3],
            'database': values[4]
        }
        print(json.dumps(result))
    except ValueError as e:
        sys.stderr.write(f'config.cache: {str(e)}\n')
        sys.exit(1)

if __name__ == '__main__':
    if len(sys.argv) < 3:
        sys.exit(1)
    command = sys.argv[1]
    if command == 'pack' and len(sys.argv) == 4:
        pack(sys.argv[2], sys.argv[3])
    elif command == 'unpack' and len(sys.argv) == 3:
        unpack(sys.argv[2])
    else:
        sys.exit(1)

