from datetime import datetime, timezone

def poll_health_endpoint():
    health_url = os.environ.get('HEALTH_URL')
    if not health_url:
        raise ValueError("HEALTH_URL environment variable is not set")

    while True:
        try:
            response = requests.get(health_url)
            response.raise_for_status()
            data = response.json()

            if 'service' in data and 'status' in data:
                log_entry = {
                    'timestamp': datetime.now(timezone.utc).isoformat(timespec='milliseconds') + 'Z',
                    'service': data['service'],
                    'status': data['status'],
                    'request_id': uuid.uuid4().hex
                }
            else:
                raise ValueError("Response JSON missing required fields")

        except Exception as e:
            log_entry = {
                'timestamp': datetime.now(timezone.utc).isoformat(timespec='milliseconds') + 'Z',
                'error': str(e)
            }

        with open('health.log', 'a') as log_file:
            log_file.write(json.dumps(log_entry) + '\n')

        time.sleep(10)

