import sys
import json
import subprocess
import shlex
import os

def load_state():
    if os.path.exists('report_state.json'):
        with open('report_state.json', 'r') as f:
            return json.load(f)
    return {}

def save_state(state):
    with open('report_state.json', 'w') as f:
        json.dump(state, f, indent=2)

def run_command(command):
    try:
        process = subprocess.Popen(shlex.split(command), stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        stdout, stderr = process.communicate()
        return process.returncode, stdout, stderr
    except Exception as e:
        return -1, '', str(e)

def main(jobs_file, report_file):
    with open(jobs_file, 'r') as f:
        jobs_data = json.load(f)

    jobs = jobs_data['jobs']
    state = load_state()

    for job in jobs:
        name = job['name']
        command = job['command']

        if name in state:
            exit_code = state[name]['exit_code']
            stdout = state[name]['stdout']
            stderr = state[name]['stderr']
        else:
            exit_code, stdout, stderr = run_command(command)
            state[name] = {
                'exit_code': exit_code,
                'stdout': stdout,
                'stderr': stderr
            }

    save_state(state)

    with open(report_file, 'w') as f:
        f.write('<!DOCTYPE html>\n<html>\n<head>\n<title>Job Report</title>\n</head>\n<body>\n')
        f.write('<h1>Job Report</h1>\n')
        f.write('<table border="1">\n')
        f.write('<tr><th>Name</th><th>Exit code</th><th>Stdout</th><th>Stderr</th></tr>\n')

        for job in jobs:
            name = job['name']
            job_state = state[name]
            f.write(f'<tr><td>{name}</td><td>{job_state["exit_code"]}</td><td>{job_state["stdout"]}</td><td>{job_state["stderr"]}</td></tr>\n')

        f.write('</table>\n')
        f.write('</body>\n</html>\n')

if __name__ == '__main__':
    if len(sys.argv) != 3:
        print('Usage: python build_report.py <jobs_file> <report_file>')
        sys.exit(1)

    jobs_file = sys.argv[1]
    report_file = sys.argv[2]
    main(jobs_file, report_file)

import sys
import xml.etree.ElementTree as ET
import sqlite3
import subprocess
import json

def main(config_xml, db_file):
    # Parse XML configuration
    tree = ET.parse(config_xml)
    root = tree.getroot()

    checks = []

    # Process each check element in order
    for check_elem in root.findall('check'):
        name = check_elem.get('name')
        check_type = check_elem.get('type')

        if not name or not check_type:
            continue

        if check_type == 'command':
            command = check_elem.text.strip() if check_elem.text else ''
            if not command:
                checks.append({
                    "name": name,
                    "type": "command",
                    "exit_code": 1,
                    "stdout": "",
                    "stderr": ""
                })
                continue

            try:
                result = subprocess.run(
                    command, 
                    shell=True, 
                    capture_output=True, 
                    text=True, 
                    encoding='utf-8'
                )
                checks.append({
                    "name": name,
                    "type": "command",
                    "exit_code": result.returncode,
                    "stdout": result.stdout,
                    "stderr": result.stderr
                })
            except Exception as e:
                checks.append({
                    "name": name,
                    "type": "command",
                    "exit_code": 1,
                    "stdout": "",
                    "stderr": str(e)
                })

        elif check_type == 'sql':
            sql_query = check_elem.text.strip() if check_elem.text else ''
            if not sql_query:
                checks.append({
                    "name": name,
                    "type": "sql",
                    "rows": []
                })
                continue

            try:
                conn = sqlite3.connect(db_file)
                cursor = conn.cursor()
                cursor.execute(sql_query)
                rows = cursor.fetchall()

                # Convert rows to JSON-compatible format
                json_rows = []
                for row in rows:
                    json_row = []
                    for value in row:
                        if value is None:
                            json_row.append(None)
                        elif isinstance(value, str):
                            json_row.append(value)
                        elif isinstance(value, int):
                            json_row.append(value)
                        elif isinstance(value, float):
                            json_row.append(value)
                        else:
                            json_row.append(str(value))
                    json_rows.append(json_row)

                checks.append({
                    "name": name,
                    "type": "sql",
                    "rows": json_rows
                })
                conn.close()

            except Exception as e:
                checks.append({
                    "name": name,
                    "type": "sql",
                    "rows": []
                })

    # Output the JSON result
    print(json.dumps({"checks": checks}, indent=None))

if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.exit(1)
    config_xml = sys.argv[1]
    db_file = sys.argv[2]
    main(config_xml, db_file)

import sys
import json
import requests
from xml.etree import ElementTree as ET

def parse_rss_xml(xml_content):
    try:
        root = ET.fromstring(xml_content)
        items = root.findall('.//{http://www.w3.org/2005/Atom}entry')
        if items:
            first_item = items[0]
            title = first_item.find('{http://www.w3.org/2005/Atom}title')
            link = first_item.find('{http://www.w3.org/2005/Atom}link')
            if title is not None and link is not None:
                return title.text, link.get('href')
        return None, None
    except Exception:
        return None, None

def main():
    if len(sys.argv) != 2:
        print(json.dumps({"feeds": []}))
        return

    config_path = sys.argv[1]

    try:
        with open(config_path, 'r') as f:
            config = json.load(f)
    except Exception as e:
        print(json.dumps({"feeds": []}))
        return

    if "feeds" not in config or not isinstance(config["feeds"], list):
        print(json.dumps({"feeds": []}))
        return

    result_feeds = []

    for feed in config["feeds"]:
        if not isinstance(feed, dict) or "name" not in feed or "url" not in feed:
            result_feeds.append({"name": feed.get("name", ""), "error": "failed"})
            continue

        name = feed["name"]
        url = feed["url"]

        try:
            response = requests.get(url, timeout=10)
            if response.status_code == 200:
                content = response.text
                # Check if it's RSS 2.0 XML
                if content.startswith('<?xml') and 'rss' in content.lower():
                    # Look for first <item> with <title> and <link>
                    root = ET.fromstring(content)
                    items = root.findall('.//item')
                    if items:
                        first_item = items[0]
                        title_elem = first_item.find('title')
                        link_elem = first_item.find('link')
                        if title_elem is not None and link_elem is not None:
                            title = title_elem.text
                            link = link_elem.text
                            result_feeds.append({
                                "name": name,
                                "title": title,
                                "link": link
                            })
                        else:
                            result_feeds.append({
                                "name": name,
                                "error": "failed"
                            })
                    else:
                        result_feeds.append({
                            "name": name,
                            "error": "failed"
                        })
                else:
                    result_feeds.append({
                        "name": name,
                        "error": "failed"
                    })
            else:
                result_feeds.append({
                    "name": name,
                    "error": "failed"
                })
        except Exception:
            result_feeds.append({
                "name": name,
                "error": "failed"
            })

    print(json.dumps({"feeds": result_feeds}))

if __name__ == "__main__":
    main()

import os
import time
import json
import requests
import uuid
from datetime import datetime
import re

HEALTH_URL = os.getenv('HEALTH_URL')

if not HEALTH_URL:
    print("Error: HEALTH_URL environment variable is not set")
    exit(1)

# Validate URL format to prevent open redirects and SSRF
def is_valid_url(url):
    if not url or not isinstance(url, str):
        return False
    # Basic pattern to ensure it starts with http(s) and has a valid domain
    pattern = r'^https?://[a-zA-Z0-9.-]+\.[a-zA-Z]{2,}(?:/[^\s]*)?$'
    return bool(re.match(pattern, url))

# Sanitize and validate response fields
def sanitize_field(value):
    if value is None:
        return ""
    if isinstance(value, str):
        # Remove potentially dangerous characters and limit length
        return re.sub(r'[^\w\s\-:]', '', value.strip())[:255]
    return str(value)

# Generate a secure, consistent request ID
def generate_request_id():
    return uuid.uuid4().hex.lower()

# Format timestamp correctly in ISO 8601 with milliseconds and Z suffix
def get_iso_timestamp():
    now = datetime.utcnow()
    return now.isoformat(' ').replace('T', 'T') + 'Z'

# Log entry with proper sanitization and validation
def log_entry(data):
    # Sanitize all fields before logging
    sanitized_data = {}
    for key, value in data.items():
        if key in ['timestamp', 'request_id']:
            sanitized_data[key] = value
        elif key in ['service', 'status', 'error']:
            sanitized_data[key] = sanitize_field(value)
        else:
            sanitized_data[key] = sanitize_field(str(value))

    # Ensure timestamp is properly formatted
    if 'timestamp' not in sanitized_data:
        sanitized_data['timestamp'] = get_iso_timestamp()

    # Write to log file
    with open('health.log', 'a') as f:
        f.write(json.dumps(sanitized_data, ensure_ascii=False) + '\n')

# Validate response body structure and content
def validate_response(body):
    if not isinstance(body, dict):
        return False, "Response is not a valid JSON object"

    required_fields = ['service', 'status']
    for field in required_fields:
        if field not in body:
            return False, f"Missing required field: {field}"

    # Validate field types and content
    service = body.get('service')
    status = body.get('status')

    if not isinstance(service, str) or not isinstance(status, str):
        return False, "Service or status field is not a string"

    # Prevent injection via field content
    if not re.match(r'^[a-zA-Z0-9\s\-_\.]+$', service):
        return False, "Invalid service name"
    if not re.match(r'^[a-zA-Z0-9\s\-_\.]+$', status):
        return False, "Invalid status value"

    return True, ""

while True:
    try:
        # Validate URL before making request
        if not is_valid_url(HEALTH_URL):
            error_msg = "Invalid URL format"
            timestamp = get_iso_timestamp()
            log_entry({
                'timestamp': timestamp,
                'error': error_msg
            })
            time.sleep(10)
            continue

        # Make request with timeout
        response = requests.get(HEALTH_URL, timeout=10)

        # Handle HTTP status codes
        if response.status_code == 200:
            try:
                body = response.json()
                is_valid, message = validate_response(body)
                if not is_valid:
                    error_msg = message
                    timestamp = get_iso_timestamp()
                    log_entry({
                        'timestamp': timestamp,
                        'error': error_msg
                    })
                else:
                    service = sanitize_field(body['service'])
                    status = sanitize_field(body['status'])
                    request_id = generate_request_id()
                    timestamp = get_iso_timestamp()
                    log_entry({
                        'timestamp': timestamp,
                        'service': service,
                        'status': status,
                        'request_id': request_id
                    })
            except Exception as e:
                error_msg = f"Failed to parse JSON response: {str(e)}"
                timestamp = get_iso_timestamp()
                log_entry({
                    'timestamp': timestamp,
                    'error': error_msg
                })
        else:
            error_msg = f"HTTP {response.status_code}"
            timestamp = get_iso_timestamp()
            log_entry({
                'timestamp': timestamp,
                'error': error_msg
            })

    except requests.exceptions.RequestException as e:
        error_msg = f"Request failed: {str(e)}"
        timestamp = get_iso_timestamp()
        log_entry({
            'timestamp': timestamp,
            'error': error_msg
        })
    except Exception as e:
        error_msg = f"Unexpected error: {str(e)}"
        timestamp = get_iso_timestamp()
        log_entry({
            'timestamp': timestamp,
            'error': error_msg
        })

    # Respect rate limits and avoid overwhelming the endpoint
    time.sleep(10)

import sys
import os
import subprocess
from html import escape
import shlex

def read_template(template_path):
    try:
        with open(template_path, 'r') as file:
            return file.read()
    except FileNotFoundError:
        print(f"Template file '{template_path}' not found.")
        sys.exit(1)

def execute_command(command):
    try:
        args = shlex.split(command)
        result = subprocess.run(args, capture_output=True, text=True)
        return {
            'command': command,
            'stdout': escape(result.stdout),
            'stderr': escape(result.stderr),
            'exit_code': result.returncode
        }
    except FileNotFoundError:
        return {
            'command': command,
            'stdout': '',
            'stderr': escape(f"Command not found: {command}"),
            'exit_code': 127
        }
    except Exception as e:
        return {
            'command': command,
            'stdout': '',
            'stderr': escape(str(e)),
            'exit_code': -1
        }

def generate_html(results):
    html_sections = []
    for result in results:
        section = f"""
<section>
<h2>{escape(result['command'])}</h2>
<pre>{result['stdout']}</pre>
<pre>{result['stderr']}</pre>
<p>Exit status: {result['exit_code']}</p>
</section>
"""
        html_sections.append(section)
    return ''.join(html_sections)

def sanitize_path(path):
    return os.path.abspath(os.path.normpath(path))

def main():
    if len(sys.argv) > 1:
        template_path = sanitize_path(sys.argv[1])
    else:
        template_path = sanitize_path('report_template.html')

    template = read_template(template_path)

    results = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            results.append(execute_command(line))

    if results:
        html_results = generate_html(results)
        final_html = template.replace('<!--RESULTS-->', html_results)
    else:
        final_html = template

    with open('build-report.html', 'w') as file:
        file.write(final_html)

if __name__ == '__main__':
    main()

import sys
import json
import sqlite3
import re
import requests
import operator
import ast

def evaluate_expression(expr):
    def eval_node(node):
        if isinstance(node, ast.BinOp):
            left = eval_node(node.left)
            right = eval_node(node.right)
            if isinstance(node.op, ast.Add):
                return left + right
            elif isinstance(node.op, ast.Sub):
                return left - right
            elif isinstance(node.op, ast.Mult):
                return left * right
            elif isinstance(node.op, ast.Div):
                return left // right
        elif isinstance(node, ast.UnaryOp):
            operand = eval_node(node.operand)
            if isinstance(node.op, ast.USub):
                return -operand
        elif isinstance(node, ast.Num):
            return node.n
        raise ValueError("Unsupported operation")

    tree = ast.parse(expr, mode='eval')
    return eval_node(tree.body)

def replace_placeholders(query, values):
    def replacer(match):
        expr = match.group(1)
        return str(evaluate_expression(expr))
    return re.sub(r'\{\{(.*?)\}\}', replacer, query)

def run_check(check):
    name = check['name']
    db_path = check['db']
    query = check['query']
    threshold = check['threshold']
    webhook = check['webhook']

    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
        query = replace_placeholders(query, {})
        cursor.execute(query)
        result = cursor.fetchone()
        conn.close()

        if result is None or len(result) == 0:
            value = 0
        else:
            value = int(result[0])

        if value > threshold:
            payload = {"check": name, "value": value}
            response = requests.post(webhook, json=payload, headers={'Content-Type': 'application/json'}, timeout=10)
            if response.status_code < 400:
                outcome = 'sent'
            else:
                outcome = 'failed'
        else:
            outcome = 'skipped'

        print(f"{name} {value} {outcome}")

    except Exception as e:
        print(f"{name} 0 failed")

def main():
    if len(sys.argv) != 2:
        print("Usage: python alertcheck.py checks.json")
        sys.exit(1)

    config_path = sys.argv[1]
    with open(config_path, 'r') as f:
        config = json.load(f)

    for check in config['checks']:
        run_check(check)

if __name__ == "__main__":
    main()
